// Bootcamp Connect prototype: demo attachments (sample images and PDFs for demo posts).
// Plain script (shared globals); load order is set in prototype.html.

// Screenshot-style images drawn as SVG so the demo needs no external image hosting.
function svgData(svg) { return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg); }

function mockPoster({ title, subtitle, from, to, emoji }) {
  return svgData(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800">
    <defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/></linearGradient></defs>
    <rect width="1200" height="800" fill="url(#g)"/>
    <circle cx="1020" cy="140" r="220" fill="#fff" opacity=".12"/><circle cx="160" cy="700" r="260" fill="#fff" opacity=".08"/>
    <text x="90" y="300" font-family="-apple-system,Helvetica,Arial" font-size="120">${emoji}</text>
    <text x="90" y="460" font-family="-apple-system,Helvetica,Arial" font-weight="700" font-size="84" fill="#fff">${title}</text>
    <text x="92" y="540" font-family="-apple-system,Helvetica,Arial" font-size="40" fill="#fff" opacity=".85">${subtitle}</text>
  </svg>`);
}

function mockBrowser({ url, accent, heading, rows }) {
  const lines = rows.map((r, i) => `<rect x="120" y="${300 + i * 92}" width="960" height="72" rx="16" fill="#F2F2F7"/>
    <text x="150" y="${345 + i * 92}" font-family="-apple-system,Helvetica,Arial" font-size="28" fill="#1C1C1E">${r[0]}</text>
    <rect x="${880 - r[1].length * 6}" y="${318 + i * 92}" width="${r[1].length * 15 + 40}" height="36" rx="18" fill="${accent}" opacity=".15"/>
    <text x="${900 - r[1].length * 6}" y="${344 + i * 92}" font-family="-apple-system,Helvetica,Arial" font-weight="600" font-size="22" fill="${accent}">${r[1]}</text>`).join('');
  return svgData(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800">
    <rect width="1200" height="800" fill="#E9EBF2"/>
    <rect x="60" y="50" width="1080" height="700" rx="22" fill="#fff"/>
    <rect x="60" y="50" width="1080" height="70" rx="22" fill="#F7F7FA"/><rect x="60" y="100" width="1080" height="20" fill="#F7F7FA"/>
    <circle cx="100" cy="85" r="9" fill="#FF5F57"/><circle cx="130" cy="85" r="9" fill="#FEBC2E"/><circle cx="160" cy="85" r="9" fill="#28C840"/>
    <rect x="300" y="68" width="600" height="34" rx="17" fill="#ECECF1"/>
    <text x="600" y="92" text-anchor="middle" font-family="-apple-system,Helvetica,Arial" font-size="20" fill="#6E6E73">${url}</text>
    <text x="120" y="230" font-family="-apple-system,Helvetica,Arial" font-weight="700" font-size="52" fill="#1C1C1E">${heading}</text>
    ${lines}
  </svg>`);
}

function mockPhone({ accent, title, items }) {
  const cards = items.map((t, i) => `<rect x="70" y="${250 + i * 120}" width="400" height="100" rx="22" fill="#fff"/>
    <circle cx="125" cy="${300 + i * 120}" r="26" fill="${accent}" opacity="${0.35 + i * 0.2}"/>
    <text x="170" y="${310 + i * 120}" font-family="-apple-system,Helvetica,Arial" font-size="28" fill="#1C1C1E">${t}</text>`).join('');
  return svgData(`<svg xmlns="http://www.w3.org/2000/svg" width="540" height="960" viewBox="0 0 540 960">
    <rect width="540" height="960" rx="60" fill="#111"/>
    <rect x="18" y="18" width="504" height="924" rx="46" fill="#F2F2F7"/>
    <rect x="200" y="36" width="140" height="34" rx="17" fill="#111"/>
    <text x="70" y="190" font-family="-apple-system,Helvetica,Arial" font-weight="700" font-size="48" fill="#1C1C1E">${title}</text>
    ${cards}
    <rect x="70" y="800" width="400" height="72" rx="36" fill="${accent}"/>
    <text x="270" y="846" text-anchor="middle" font-family="-apple-system,Helvetica,Arial" font-weight="600" font-size="28" fill="#fff">Start session</text>
  </svg>`);
}

const DEMO_FILES = {
  unitEcon: 'data:application/pdf;base64,',
  interviews: 'data:application/pdf;base64,',
};
